const data = $json;
const stats = {
  open: data.open_tasks ?? 0,
  inProgress: data.in_progress ?? 0,
  completedToday: data.completed_today ?? 0,
  rewardPool: data.total_reward_pool ?? 0
};
const tasks = data.active_tasks || [];

const urgencyLabel = { high: 'СРОЧНО', medium: 'средний', low: 'низкий' };
const taskList = tasks.length > 0
  ? tasks.map((t, i) =>
      `${i + 1}. [${urgencyLabel[t.urgency] || t.urgency}] ${t.shortDescription} — ${t.reward}₸ (${t.city})`
    ).join('\n')
  : 'Нет активных задач';

const highPriorityCount = tasks.filter(t => t.urgency === 'high').length;

const prompt = `Ты — ассистент платформы TaskOnDemand (биржа задач). Сделай краткий утренний дайджест на русском языке.\n\nСтатистика:\n- Открытых задач: ${stats.open}\n- В работе: ${stats.inProgress}\n- Выполнено сегодня: ${stats.completedToday}\n- Суммарный reward pool: ${stats.rewardPool}₸\n- Срочных задач: ${highPriorityCount}\n\nАктивные задачи:\n${taskList}\n\nНапиши дружелюбный дайджест в 3-4 предложения. Если есть срочные задачи — выдели их. Используй эмодзи.`;

return { prompt, stats, taskCount: tasks.length, highPriorityCount };

const aiAnswer = $json?.choices?.[0]?.message?.content ?? 'AI не ответил.';
const prev = $('Build AI Prompt').item.json;
const stats = prev.stats;
const d = new Date();
const dateStr = d.toLocaleDateString('ru-RU', { weekday: 'long', day: 'numeric', month: 'long', timeZone: 'Asia/Almaty' });

const text = [
  `📋 <b>Дайджест TaskOnDemand</b>`,
  `📅 ${dateStr}`,
  ``,
  aiAnswer,
  ``,
  `📊 <b>Статистика:</b>`,
  `• Открыто: ${stats.open} | В работе: ${stats.inProgress} | Выполнено сегодня: ${stats.completedToday}`,
  `• 💰 Reward pool: ${stats.rewardPool}₸`
].join('\n');

return { text };
